<?php
require_once __DIR__.'/../config/auth.php'; ensure_assessment_tables();require_login();
$rows=db()->query("SELECT u.nome,COUNT(t.id) provas,ROUND(AVG(t.nota),2) media,MAX(t.nota) melhor FROM usuarios u JOIN prova_tentativas t ON t.usuario_id=u.id WHERE u.tipo='aluno' AND t.status IN ('finalizada','expirada') GROUP BY u.id,u.nome ORDER BY media DESC,melhor DESC,u.nome ASC LIMIT 20")->fetchAll();
$pageTitle='Ranking de desempenho';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><section class="panel"><h2>Ranking de desempenho</h2><p class="subtext">Classificação calculada pela média das notas das provas realizadas.</p><div class="table-wrap"><table><thead><tr><th>#</th><th>Aluno</th><th>Provas</th><th>Média</th><th>Melhor nota</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><b><?=$i+1?></b></td><td><?=e($r['nome'])?></td><td><?=$r['provas']?></td><td><?=number_format((float)$r['media'],2,',','.')?></td><td><?=number_format((float)$r['melhor'],2,',','.')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">Ainda não existem resultados de provas.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
